package web

import (
	"bytes"
	"embed"
	"io/fs"
	"log"
	"net/http"
	"path"
	"strings"
	"time"
)

//go:embed all:out
var staticFiles embed.FS

// dynamicRoutes maps route prefixes of Next dynamic segments to the single
// placeholder page generated by generateStaticParams ("_").
var dynamicRoutes = []string{"customers", "catalogo"}

// FileServer serves the embedded, statically exported frontend.
func FileServer() http.Handler {
	frontendFS, err := fs.Sub(staticFiles, "out")
	if err != nil {
		log.Fatalf("failed to prepare static files: %v", err)
	}
	return newFileServer(frontendFS)
}

// newFileServer resolves a request path in this order: exact file,
// <route>.html, dynamic placeholder, 404 for assets, index.html (SPA fallback).
func newFileServer(fsys fs.FS) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		p := strings.Trim(path.Clean("/"+r.URL.Path), "/")
		if p == "" {
			serveFile(w, r, fsys, "index.html")
			return
		}
		if isFile(fsys, p) {
			serveFile(w, r, fsys, p)
			return
		}
		if isFile(fsys, p+".html") {
			serveFile(w, r, fsys, p+".html")
			return
		}
		for _, prefix := range dynamicRoutes {
			if strings.HasPrefix(p, prefix+"/") && isFile(fsys, prefix+"/_.html") {
				serveFile(w, r, fsys, prefix+"/_.html")
				return
			}
		}
		if strings.HasPrefix(p, "_next/") || path.Ext(p) != "" {
			http.NotFound(w, r)
			return
		}
		serveFile(w, r, fsys, "index.html")
	})
}

func isFile(fsys fs.FS, name string) bool {
	info, err := fs.Stat(fsys, name)
	return err == nil && !info.IsDir()
}

func serveFile(w http.ResponseWriter, r *http.Request, fsys fs.FS, name string) {
	data, err := fs.ReadFile(fsys, name)
	if err != nil {
		http.NotFound(w, r)
		return
	}
	http.ServeContent(w, r, name, time.Time{}, bytes.NewReader(data))
}
